python etl_pipeline.py --execute true <<'EOF'
{
  "defs": {
    "Enrich": { "steps":[
      {"op":"map","as":"enriched","expr":"value * params.multiplier"}
    ]},
    "Process": { "steps":[
      {"op":"filter","where":"enriched > params.min_value"},
      {"op":"rename","from":"enriched","to":"processed_value"}
    ]}
  },
  "pipeline": {
    "steps": [
      {"op":"call","name":"Enrich","params":{"multiplier":2}},
      {"op":"call","name":"Process","params":{"min_value":10}},
      {"op":"select","columns":["id","processed_value"]}
    ]
  },
  "dataset":[
    {"id":1,"value":3},
    {"id":2,"value":8},
    {"id":3,"value":10}
  ]
}
EOF

python etl_pipeline.py --execute true <<'EOF'
{
  "defs": {
    "EnhanceData": { "steps":[
      {"op":"map","as":"enhanced","expr":"id * params.scale"}
    ]},
    "ConditionalProcess": { "steps":[
      {"op":"branch","branches":[
        {"when":"enhanced > params.threshold","steps":[
          {"op":"map","as":"status","expr":"'high'"}
        ]},
        {"when":"otherwise","steps":[
          {"op":"map","as":"status","expr":"'low'"}
        ]}
      ]},
      {"op":"limit","n":params.limit}
    ]}
  },
  "pipeline": {
    "steps": [
      {"op":"call","name":"EnhanceData","params":{"scale":10}},
      {"op":"call","name":"ConditionalProcess","params":{"threshold":50,"limit":2}},
      {"op":"select","columns":["id","enhanced","status"]},
      {"op":"rename","from":"enhanced","to":"final_value"}
    ]
  },
  "dataset":[
    {"id":3,"value":"test1"},
    {"id":6,"value":"test2"},
    {"id":9,"value":"test3"},
    {"id":2,"value":"test4"}
  ]
}
EOF

